const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const sanJuan = ee.Geometry.Point(-66.06, 18.42); // Approximate center of San Juan, Puerto Rico

  const startDateP1 = '2017-09-01';
  const endDateP1 = '2017-09-02'; // Includes Sep 1 and Sep 2

  const startDateP2 = '2017-09-27';
  const endDateP2 = '2017-09-28'; // Includes Sep 27 and Sep 28

  const viirsCollection = ee.ImageCollection('NOAA/VIIRS/DNB/DAILY_V2');
  const bandName = 'avg_rad'; // Average Radiance

  // 2. Data Acquisition & Check - Period 1
  let collectionP1 = viirsCollection
    .filterDate(startDateP1, ee.Date(endDateP1).advance(1, 'day')) // Filter to include the end date
    .filterBounds(sanJuan)
    .select(bandName);

  const sizeP1 = await collectionP1.size().getInfo();
  if (sizeP1 === 0) {
    console.log("C1: No VIIRS DNB data found for San Juan on Sep 1-2, 2017.");
    console.log("C1");
    return;
  }

  // 2. Data Acquisition & Check - Period 2
  let collectionP2 = viirsCollection
    .filterDate(startDateP2, ee.Date(endDateP2).advance(1, 'day')) // Filter to include the end date
    .filterBounds(sanJuan)
    .select(bandName);

  const sizeP2 = await collectionP2.size().getInfo();
  if (sizeP2 === 0) {
    console.log("C1: No VIIRS DNB data found for San Juan on Sep 27-28, 2017.");
    console.log("C1");
    return;
  }

  // 3. Processing
  // Take the mean over the collection for each period to get a single image
  const imageP1 = collectionP1.mean();
  const imageP2 = collectionP2.mean();

  const scale = 750; // VIIRS DNB resolution is ~750m

  // Calculate pixel count for Period 1
  const countP1 = await imageP1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: sanJuan,
    scale: scale,
    maxPixels: 1e9
  }).get(bandName).getInfo();

  if (countP1 === 0) {
    console.log("C2: No valid pixels for San Juan after processing for Sep 1-2, 2017.");
    console.log("C2");
    return;
  }

  // Calculate pixel count for Period 2
  const countP2 = await imageP2.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: sanJuan,
    scale: scale,
    maxPixels: 1e9
  }).get(bandName).getInfo();

  if (countP2 === 0) {
    console.log("C2: No valid pixels for San Juan after processing for Sep 27-28, 2017.");
    console.log("C2");
    return;
  }

  // 4. Calculation
  const brightnessP1 = await imageP1.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: sanJuan,
    scale: scale,
    maxPixels: 1e9
  }).get(bandName).getInfo();

  const brightnessP2 = await imageP2.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: sanJuan,
    scale: scale,
    maxPixels: 1e9
  }).get(bandName).getInfo();

  // 5. Validation & Final Answer
  if (brightnessP1 === null || isNaN(brightnessP1) || brightnessP2 === null || isNaN(brightnessP2)) {
    console.log("C3: Calculation of mean brightness returned null or NaN.");
    console.log("C3");
    return;
  }

  console.log(`Sep 1-2, 2017: Images: ${sizeP1}, Valid Pixels: ${countP1}, Avg Brightness: ${brightnessP1.toFixed(4)}`);
  console.log(`Sep 27-28, 2017: Images: ${sizeP2}, Valid Pixels: ${countP2}, Avg Brightness: ${brightnessP2.toFixed(4)}`);

  if (brightnessP2 < brightnessP1) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
